use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

/// The node's `with` clause: the only hosts this node may reach.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Checks a subscription URL against the node's grant before any fetch.
/// The host enforces the same allowlist and traps on a violation, which
/// cannot be caught, so out-of-scope URLs are reported as failures here
/// instead of reaching the boundary.
fn check_allowed(url: &str) -> Result<(), String> {
    if url.chars().any(|c| c.is_whitespace() || c.is_control()) {
        return Err("url contains whitespace or control characters".to_string());
    }

    let rest = url
        .strip_prefix("https://")
        .ok_or_else(|| "unsupported scheme (https only)".to_string())?;

    let authority = rest
        .split(|c: char| matches!(c, '/' | '?' | '#'))
        .next()
        .unwrap_or("");

    if authority.is_empty() {
        return Err("missing host".to_string());
    }
    if authority.contains('@') {
        return Err("userinfo in url is not allowed".to_string());
    }
    if authority.contains('[') {
        return Err("ipv6 literal hosts are not allowed".to_string());
    }

    let host = match authority.split_once(':') {
        Some((host, port)) => {
            if !port.chars().all(|c| c.is_ascii_digit()) {
                return Err("invalid port".to_string());
            }
            host
        }
        None => authority,
    };

    let host = host.to_ascii_lowercase();
    if ALLOWED_HOSTS.iter().any(|allowed| *allowed == host) {
        Ok(())
    } else {
        Err(format!("host {host} is not in this node's allowlist"))
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            if let Err(error) = check_allowed(&url) {
                failures.push(FetchFailure { url, error });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
